//! Native and WebAssembly CPU implementation of the Roast Solver.
//!
//! The numerical contract mirrors `roast_solver/`: SI geometry and fluxes,
//! Celsius state, a conservative 7-point stencil, an interior level-set shell
//! for embedded-boundary area, radiation, finite surface-water reservoirs,
//! cook/rest phases, and conservative pasteurization integration.

use serde::{Deserialize, Serialize};
use std::f64::consts::PI;

const SIGMA: f64 = 5.670_374_419e-8;
const H_FG: f64 = 2.256e6;
const BIRD_UNIT_VOLUME: f64 = 1.702_286_069_853_643;

#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(default)]
pub struct Input {
    pub preset: String,
    pub mass_kg: f64,
    pub resolution: usize,
    pub material_density: f64,
    pub initial_c: f64,
    pub target_c: f64,
    pub oven_c: f64,
    pub convection_h: f64,
    pub emissivity: f64,
    pub wall_c: Option<f64>,
    pub covered: bool,
    pub ambient_vapor_density: f64,
    pub lewis_number: f64,
    pub surface_water_kg_m2: f64,
    pub pan_insulated: bool,
    pub max_cook_s: f64,
    pub rest_s: f64,
    pub sample_interval_s: f64,
    pub requested_dt_s: f64,
    pub rest_ambient_c: f64,
    pub rest_h: f64,
    pub foil_tent: bool,
    pub pasteurization_ref_c: f64,
    pub pasteurization_z_c: f64,
    pub denaturation_bump: bool,
}

impl Default for Input {
    fn default() -> Self {
        Self {
            preset: "roast".into(), mass_kg: 1.0, resolution: 32, material_density: 1060.0,
            initial_c: 5.0, target_c: 55.0, oven_c: 180.0, convection_h: 10.0,
            emissivity: 0.9, wall_c: None, covered: false, ambient_vapor_density: 0.010,
            lewis_number: 0.90, surface_water_kg_m2: 0.25, pan_insulated: true,
            max_cook_s: 5.0 * 3600.0, rest_s: 30.0 * 60.0, sample_interval_s: 30.0,
            requested_dt_s: 30.0, rest_ambient_c: 22.0, rest_h: 7.0, foil_tent: false,
            pasteurization_ref_c: 70.0, pasteurization_z_c: 10.0, denaturation_bump: false,
        }
    }
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Record {
    pub time_s: f64,
    pub coldest_c: f64,
    pub probe_c: f64,
    pub surface_mean_c: f64,
    pub pasteurization_equivalent_min: f64,
    pub phase: String,
}

#[derive(Clone, Debug, Default, Serialize, Deserialize)]
pub struct Energy {
    pub convection_j: f64,
    pub radiation_j: f64,
    pub evaporation_j: f64,
    pub net_surface_j: f64,
    pub enthalpy_change_j: f64,
    pub relative_balance_error: f64,
}

#[derive(Clone, Debug, Serialize)]
pub struct Chunk {
    pub records: Vec<Record>,
    pub done: bool,
    pub phase: String,
    pub progress: f64,
    pub dimensions_zyx: [usize; 3],
    pub temperatures_c: Vec<f32>,
    pub inside: Vec<bool>,
    pub pull_time_s: Option<f64>,
    pub pull_reached: bool,
    pub peak_core_c: f64,
    pub peak_time_s: f64,
    pub carryover_c: f64,
    pub dt_s: f64,
    pub energy: Energy,
}

#[derive(Clone, Debug)]
struct Geometry {
    dims: [usize; 3],
    phi: Vec<f64>,
    inside: Vec<bool>,
    area: Vec<f64>,
    pan: Vec<bool>,
    h: f64,
}

impl Geometry {
    fn idx(&self, z: usize, y: usize, x: usize) -> usize {
        (z * self.dims[1] + y) * self.dims[2] + x
    }
}

fn component_density(t: f64) -> [f64; 5] {
    let t = t.clamp(-20.0, 150.0);
    [997.18 + 3.1439e-3*t - 3.7574e-3*t*t, 1329.9 - 0.5184*t,
     925.59 - 0.41757*t, 1599.1 - 0.31046*t, 2423.8 - 0.28063*t]
}
fn component_cp(t: f64) -> [f64; 5] {
    let t = t.clamp(-20.0, 150.0);
    [4176.2 - 0.0909*t + 5.4731e-3*t*t, 2008.2 + 1.2089*t - 1.3129e-3*t*t,
     1984.2 + 1.4733*t - 4.8008e-3*t*t, 1548.8 + 1.9625*t - 5.9399e-3*t*t,
     1092.6 + 1.8896*t - 3.6817e-3*t*t]
}
fn component_k(t: f64) -> [f64; 5] {
    let t = t.clamp(-20.0, 150.0);
    [0.57109 + 1.7625e-3*t - 6.7036e-6*t*t, 0.17881 + 1.1958e-3*t - 2.7178e-6*t*t,
     0.18071 - 2.7604e-4*t - 1.7749e-7*t*t, 0.20141 + 1.3874e-3*t - 4.3312e-6*t*t,
     0.32962 + 1.4011e-3*t - 2.9069e-6*t*t]
}
const X: [f64; 5] = [0.75, 0.20, 0.03, 0.005, 0.015];
pub fn density(t: f64) -> f64 {
    let r = component_density(t); 1.0 / (0..5).map(|i| X[i]/r[i]).sum::<f64>()
}
pub fn heat_capacity(t: f64, bump: bool) -> f64 {
    let c = component_cp(t);
    let mut v = (0..5).map(|i| X[i]*c[i]).sum::<f64>();
    if bump { v += 120.0 * (-0.5*((t.clamp(-20.0,150.0)-60.0)/7.0).powi(2)).exp(); }
    v
}
pub fn conductivity(t: f64) -> f64 {
    let r = component_density(t); let k = component_k(t);
    let volume: f64 = (0..5).map(|i| X[i]/r[i]).sum();
    (0..5).map(|i| (X[i]/r[i])/volume*k[i]).sum()
}
pub fn diffusivity(t: f64) -> f64 { conductivity(t)/(density(t)*heat_capacity(t, false)) }

fn ellipsoid(x:f64,y:f64,z:f64,a:f64,b:f64,c:f64)->f64 {
    let q=((x/a).powi(2)+(y/b).powi(2)+(z/c).powi(2)).sqrt();
    (q-1.0)*(x*x+y*y+z*z).sqrt()/q.max(1e-12)
}
fn capsule(x:f64,y:f64,z:f64,a:[f64;3],b:[f64;3],r:f64)->f64 {
    let p=[x-a[0],y-a[1],z-a[2]]; let ba=[b[0]-a[0],b[1]-a[1],b[2]-a[2]];
    let dot=p[0]*ba[0]+p[1]*ba[1]+p[2]*ba[2];
    let den=ba[0]*ba[0]+ba[1]*ba[1]+ba[2]*ba[2]; let q=(dot/den).clamp(0.0,1.0);
    ((p[0]-q*ba[0]).powi(2)+(p[1]-q*ba[1]).powi(2)+(p[2]-q*ba[2]).powi(2)).sqrt()-r
}
fn bird(x:f64,y:f64,z:f64)->f64 {
    let mut outside=ellipsoid(x,y,z,1.0,0.67,0.62);
    for d in [capsule(x,y,z,[-.60,-.40,-.18],[-1.20,-.50,-.28],.20),
              capsule(x,y,z,[-.60,.40,-.18],[-1.20,.50,-.28],.20),
              capsule(x,y,z,[.20,-.58,.08],[.65,-.83,-.02],.12),
              capsule(x,y,z,[.20,.58,.08],[.65,.83,-.02],.12)] { outside=outside.min(d); }
    outside.max(-ellipsoid(x-.16,y,z+.01,.50,.35,.34))
}
fn rounded_box(x:f64,y:f64,z:f64,h:[f64;3],r:f64)->f64 {
    let q=[x.abs()-(h[0]-r),y.abs()-(h[1]-r),z.abs()-(h[2]-r)];
    (q[0].max(0.0).powi(2)+q[1].max(0.0).powi(2)+q[2].max(0.0).powi(2)).sqrt()
        + q[0].max(q[1].max(q[2])).min(0.0)-r
}

fn make_geometry(input:&Input)->Result<Geometry,String> {
    if input.mass_kg<=0.0 || input.resolution<12 { return Err("mass must be positive and resolution at least 12".into()); }
    let volume=input.mass_kg/input.material_density; let preset=input.preset.to_lowercase();
    let (ext,longest,kind):( [f64;3], f64, u8 )=match preset.as_str() {
        "roast"=>{ let r=[1.0,.68,.58]; let n=2.5; let gamma=0.887_263_817_503_075_3_f64; // gamma(1.4)
            let gamma22=1.101_802_490_879_712_8_f64; // gamma(2.2)
            let uv=8.0*r[0]*r[1]*r[2]*gamma.powi(3)/gamma22; let s=(volume/uv).cbrt();
            ([s*r[0],s*r[1],s*r[2]],2.0*s,0) },
        "bird"=>{let s=(volume/BIRD_UNIT_VOLUME).cbrt();([1.45*s,1.0*s,.8*s],2.65*s,1)},
        "slab"=>{let r=[1.0,.72,.28];let s=(volume/(8.0*r[0]*r[1]*r[2])).cbrt();([s*r[0],s*r[1],s*r[2]],2.0*s,2)},
        "ham"|"sphere"=>{let r=(3.0*volume/(4.0*PI)).cbrt();([r,r,r],2.0*r,3)},
        _=>return Err(format!("unknown preset {:?}",input.preset)),
    };
    let h=longest/input.resolution as f64; let margin=2.5*h;
    let dims=[((2.0*ext[2]+2.0*margin)/h).ceil() as usize,
              ((2.0*ext[1]+2.0*margin)/h).ceil() as usize,
              ((2.0*ext[0]+2.0*margin)/h).ceil() as usize];
    let lo=[-ext[0]-margin,-ext[1]-margin,-ext[2]-margin]; let n=dims.iter().product();
    let mut phi=vec![0.0;n]; let mut inside=vec![false;n];
    for z in 0..dims[0] {for y in 0..dims[1] {for x in 0..dims[2] {
        let xx=lo[0]+(x as f64+.5)*h;let yy=lo[1]+(y as f64+.5)*h;let zz=lo[2]+(z as f64+.5)*h;
        let p=match kind {0=>{let q=((xx/ext[0]).abs().powf(2.5)+(yy/ext[1]).abs().powf(2.5)+(zz/ext[2]).abs().powf(2.5)).powf(0.4);(q-1.0)*ext[2]},
            1=>{let s=ext[0]/1.45;s*bird(xx/s,yy/s,zz/s)},2=>rounded_box(xx,yy,zz,ext,.1*(2.0*ext[2])),_=>(xx*xx+yy*yy+zz*zz).sqrt()-ext[0]};
        let i=(z*dims[1]+y)*dims[2]+x;phi[i]=p;inside[i]=p<=0.0;
    }}}
    let mut area=vec![0.0;n];let mut nz=vec![0.0;n];let mut bottom=f64::INFINITY;let mut top=f64::NEG_INFINITY;
    for z in 0..dims[0] {for y in 0..dims[1] {for x in 0..dims[2] {let i=(z*dims[1]+y)*dims[2]+x;
        if inside[i] {let zz=lo[2]+(z as f64+.5)*h;bottom=bottom.min(zz);top=top.max(zz);}
        let deriv=|axis:usize| {let (p0,p1,den)=match axis {0=>{if x==0{(i,i+1,h)}else if x+1==dims[2]{(i-1,i,h)}else{(i-1,i+1,2.0*h)}},
            1=>{if y==0{(i,i+dims[2],h)}else if y+1==dims[1]{(i-dims[2],i,h)}else{(i-dims[2],i+dims[2],2.0*h)}},
            _=>{let s=dims[1]*dims[2];if z==0{(i,i+s,h)}else if z+1==dims[0]{(i-s,i,h)}else{(i-s,i+s,2.0*h)}}};(phi[p1]-phi[p0])/den};
        let gx=deriv(0);let gy=deriv(1);let gz=deriv(2);let gn=(gx*gx+gy*gy+gz*gz).sqrt();
        if inside[i]&&phi[i]>=-h {area[i]=h*h*gn;nz[i]=gz/gn.max(1e-12);}
    }}}
    if !area.iter().any(|a|*a>0.0){return Err("grid has no resolved boundary".into());}
    let height=top-bottom+h;let mut pan=vec![false;n];
