pub fn simulate(input:Input)->Result<Chunk,String>{let mut e=Engine::new(input)?;while !e.run_steps(10_000).done{}Ok(e.chunk())}

#[cfg(feature="wasm")]
mod wasm_api {
    use super::*; use wasm_bindgen::prelude::*;
    #[wasm_bindgen]
    pub struct WasmSimulation { engine: Engine }
    #[wasm_bindgen]
    impl WasmSimulation {
        #[wasm_bindgen(constructor)]
        pub fn new(input_json:&str)->Result<WasmSimulation,JsValue>{let input:Input=serde_json::from_str(input_json).map_err(|e|JsValue::from_str(&e.to_string()))?;Engine::new(input).map(|engine|Self{engine}).map_err(|e|JsValue::from_str(&e))}
        pub fn run_chunk(&mut self,max_steps:usize)->Result<String,JsValue>{serde_json::to_string(&self.engine.run_steps(max_steps)).map_err(|e|JsValue::from_str(&e.to_string()))}
    }
    #[wasm_bindgen]
    pub fn properties_json(t:f64)->String{serde_json::json!({"density":density(t),"heat_capacity":heat_capacity(t,false),"conductivity":conductivity(t),"diffusivity":diffusivity(t)}).to_string()}
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test] fn property_ranges(){assert!((density(20.0)-1060.0).abs()<20.0);assert!(heat_capacity(20.0,false)>3500.0);assert!(conductivity(20.0)>.4);}
