    #[test] fn short_run_balances(){let mut i=Input::default();i.resolution=12;i.max_cook_s=30.0;i.rest_s=0.0;i.target_c=999.0;i.requested_dt_s=1.0;let r=simulate(i).unwrap();assert!(r.done);assert!(r.energy.relative_balance_error<2e-4);assert!(r.temperatures_c.iter().all(|v|v.is_finite()));}
}

