pub fn simulate(input: Input) -> Result<Chunk, String> {
    let mut e = Engine::new(input)?;
    let mut records = Vec::new();
    loop {
        let mut chunk = e.run_steps(10_000);
        records.append(&mut chunk.records);
        if chunk.done {
            chunk.records = records;
            return Ok(chunk);
        }
    }
}

